export const REVISION_HTML = "<!doctype html>\n<html lang=\"en-AU\" data-mode=\"published\" data-tpl=\"1\" data-boot=\"archive\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<meta name=\"referrer\" content=\"no-referrer\">\n<meta name=\"color-scheme\" content=\"dark light\">\n<title data-field=\"documentTitle\" data-empty=\"Private proposal · TEXC\">Sent revision · TEXC Proposals</title>\n<link rel=\"icon\" href=\"/assets/img/logo/TEXC-Gold.svg\" type=\"image/svg+xml\">\n<link rel=\"preload\" href=\"/assets/fonts/Oxanium-800-latin.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n<link rel=\"stylesheet\" href=\"/assets/css/tokens.css\">\n<link rel=\"stylesheet\" href=\"/assets/css/proposal.css\">\n<link rel=\"stylesheet\" href=\"/assets/css/print.css\" media=\"print\">\n<link rel=\"stylesheet\" href=\"/assets/css/revision-view.css\">\n<script type=\"application/json\" id=\"brand-data\">{\"name\":\"TEXC\",\"legalName\":\"TEXC Pty Ltd\",\"abn\":\"47 688 368 881\",\"tagline\":\"The Explosive Contractor. Wherever you need one.\",\"positioning\":\"Shotfiring & Relief Services\",\"phoneDisplay\":\"0467 651 182\",\"phoneHref\":\"tel:0467651182\",\"email\":\"management@texc.au\",\"web\":\"texc.au\",\"webHref\":\"https://texc.au\",\"principalName\":\"George Scott\",\"principalRole\":\"Managing Director | Licensed Shotfirer\",\"signoff\":\"Regards,\",\"refPrefix\":\"TEXC-P\",\"logoGold\":\"/assets/img/logo/TEXC-Gold.svg\",\"logoWhite\":\"/assets/img/logo/TEXC-White.svg\",\"logoBlack\":\"/assets/img/logo/TEXC-Black.svg\",\"privacyHref\":\"/privacy/\",\"colours\":{\"ink\":\"#111111\",\"gold\":\"#c59e42\",\"paper\":\"#f4f2ec\",\"goldOnPaper\":\"#7a5b17\"}}</script>\n<script type=\"application/json\" id=\"template-data\">{\"version\":1,\"locked\":{\"preliminaryStatus\":\"This proposal is not a final blast design or authority to undertake blasting. Final work areas, methodology and controls remain subject to further exposure, assessment and applicable approvals.\",\"noBlastingUntil\":\"No blasting activity will proceed until the relevant work area has been assessed, required controls have been confirmed, and applicable approvals and authorisations are in place.\",\"progressive\":\"The work is expected to be undertaken progressively rather than as a single unrestricted blast. Each section will be treated as its own controlled work area and reassessed before progression.\",\"paramsLine\":\"Parameters are preliminary and indicative only. This proposal is not a final blast design or authority to undertake blasting.\",\"sitePlanLabel\":\"APPROVED PROJECT MAP — DO NOT REDRAW OR INFER BOUNDARIES\",\"envLimitsNote\":\"Limits as set by the site approval / regulator — supplied by client.\",\"misfire\":\"If you are dealing with an active misfire, call {name} on {phoneDisplay} — this proposal is not an emergency channel.\",\"emergency000\":\"For immediate danger or an active emergency, contact emergency services on 000. This proposal is not an emergency-response service.\",\"hp1Framing\":\"Acceptance of the quotation and preliminary risk assessment permits progression of planning and site preparation only and does not constitute unconditional authority to undertake blasting.\"},\"snap\":{\"about\":{\"support\":{\"eyebrow\":\"Support, not competition\",\"heading\":\"Built to support established contractors.\",\"body\":\"Rather than competing against established blasting contractors, TEXC was built to support them — integrating into existing operations for a single day or the long term, working within your systems or approved TEXC procedures.\",\"quote\":\"We don't see other blasting contractors as competitors. We see them as potential clients and project partners.\"},\"working\":{\"eyebrow\":\"Working with TEXC\",\"heading\":\"What it should feel like.\",\"steps\":[{\"number\":\"01\",\"title\":\"Straightforward\",\"body\":\"Easy to engage, with a clear path from enquiry to work on site.\"},{\"number\":\"02\",\"title\":\"Responsive\",\"body\":\"We work to keep communication clear and lead times short.\"},{\"number\":\"03\",\"title\":\"Professional\",\"body\":\"Considered planning, documentation and compliance on every job.\"},{\"number\":\"04\",\"title\":\"Practical\",\"body\":\"Real support that fits how your project actually runs.\"}]}},\"competency\":{\"heading\":\"Competency sits with the person doing the work.\",\"body\":\"Units of competency and dangerous-goods licences are held by individuals, not by the company. TEXC does not present personal qualifications as company qualifications. What TEXC provides is the insurance, systems and approvals those people work inside — and the assurance that whoever turns up holds what the job requires.\"},\"assurance\":{\"title\":\"Insurance, licensing & certification\",\"body\":\"Specific insurance cover, licences and certifications are confirmed directly on enquiry and provided as supporting documentation where required. We publish these only once verified — no certification marks are shown here decoratively.\"},\"scopeNote\":\"Service scope is subject to site approvals, procedures, documentation and applicable requirements. Availability is confirmed on enquiry.\",\"workflow\":{\"intro\":\"Every blasting project follows a structured process to ensure explosives remain fully accounted for from the moment they leave the magazine until the project is complete.\"}},\"services\":[{\"slug\":\"relief-shotfiring\",\"name\":\"Relief Shotfiring\",\"category\":\"Relief Shotfiring\",\"value\":\"Additional capability whenever it is required — experienced shotfirers ready to step in on short notice.\",\"overview\":[\"Shotfirers take leave, get sick, move on, and operations can simply reach the limits of their existing capability. When that creates a gap, TEXC provides experienced shotfirers who can step in and keep the work moving.\",\"Whether supporting a quarry, mine, civil project or existing blasting contractor, we integrate into your systems, inductions and procedures — providing additional capability that feels like an extension of your own team.\"],\"capabilities\":[\"Leave and vacancy cover\",\"Peak-workload support\",\"Shutdown and campaign support\",\"Short-notice mobilisation\",\"Production, trim and secondary blasting\",\"Work within your approved systems\"],\"integrate\":\"TEXC operates within your approved client systems, inductions and site procedures. Mobilisation can be arranged promptly, with minimal lead time, so relief cover integrates cleanly with your existing operation.\",\"safety\":\"All work is planned to considered risk assessment and documentation, aligned with your site procedures and applicable legislative requirements. Availability is confirmed on enquiry — engagement does not guarantee immediate availability.\",\"pending\":false},{\"slug\":\"civil-construction\",\"name\":\"Civil Construction\",\"category\":\"Civil Construction\",\"value\":\"Supporting civil contractors through controlled blasting and specialist shotfiring services.\",\"overview\":[\"Civil projects often require specialist blasting capability as part of a broader scope of works. TEXC provides controlled rock excavation and experienced shotfiring support to keep the project moving.\",\"We work in plain English, identify what's required, and integrate with your program and site requirements.\"],\"capabilities\":[\"Rock excavation\",\"Foundation and footing excavations\",\"Utility corridors\",\"Subdivisions and road construction\",\"Infrastructure projects\",\"Controlled preparation and shotfiring\"],\"integrate\":\"TEXC integrates with your civil program, site controls and documentation. We identify the required next steps so you can plan blasting around the rest of the works with confidence.\",\"safety\":\"Controlled blasting is planned to project-specific risk assessment, with vibration and impact managed and monitored. Work is subject to site approvals, procedures and applicable requirements.\",\"pending\":false},{\"slug\":\"quarry-mining\",\"name\":\"Quarry & Mining\",\"category\":\"Quarry & Mining\",\"value\":\"Flexible support for production, development and project blasting.\",\"overview\":[\"Quarry and mining operations need competent, experienced personnel who can integrate quickly and work to site systems. TEXC provides that capability on a short-term or ongoing basis.\",\"From production blasting to additional manpower through a busy period, we slot into your operation and keep benches moving.\"],\"capabilities\":[\"Production blasting\",\"Development blasting\",\"Relief shotfiring\",\"Blast supervision\",\"Additional manpower\",\"Short-term project support\"],\"integrate\":\"TEXC works within your site systems, inductions and procedures, supplying experienced personnel who integrate with your existing crew and operation.\",\"safety\":\"All work follows considered risk assessment, documentation and your site procedures, aligned with applicable legislative requirements. Scope and availability are confirmed on enquiry.\",\"pending\":false},{\"slug\":\"microblasting\",\"name\":\"Microblasting\",\"category\":\"Microblasting\",\"value\":\"Precision blasting for sensitive environments — controlled, monitored and carefully planned.\",\"overview\":[\"Microblasting is used where rock removal is required close to buildings, services or people. It relies on careful planning, monitoring and controlled execution rather than scale.\",\"TEXC assesses the site, designs the blast around the surrounding environment, and controls each stage to achieve the required result safely and efficiently.\"],\"capabilities\":[\"Residential rock removal\",\"Commercial and industrial sites\",\"Restricted-access work\",\"Controlled vibration\",\"Precision rock removal\",\"Monitoring and assessment\"],\"integrate\":\"TEXC plans microblasting around site conditions, approvals and monitoring requirements, and coordinates with you and any relevant stakeholders throughout.\",\"safety\":\"Work is planned to project-specific risk assessment with vibration monitoring where required, subject to site conditions and approvals. TEXC does not guarantee zero vibration, zero disturbance or specific approval outcomes.\",\"pending\":false},{\"slug\":\"shot-sleeping\",\"name\":\"Shot Sleeping\",\"category\":\"Shot Sleeping\",\"value\":\"Professional overnight attendance of charged blasts, with clear handover documentation.\",\"overview\":[\"Where a charged blast cannot be fired the same day, it may need to be held securely overnight and fired the following day. TEXC provides professional attendance for these situations.\",\"The operational benefit is continuity — the shot is managed and documented so firing can proceed the following day without delay.\"],\"capabilities\":[\"Overnight security attendance\",\"Sleep shots\",\"Next-day firing\",\"Multi-shift blasts\",\"Compliance\",\"Handover documentation\"],\"integrate\":\"TEXC coordinates the overnight process with your site and procedures, providing clear handover documentation so the following steps proceed smoothly.\",\"safety\":\"Shot sleeping is subject to site approvals, procedures, documentation and applicable requirements. Procedural detail is managed with your site rather than published.\",\"pending\":false},{\"slug\":\"misfire-management\",\"name\":\"Misfire Management\",\"category\":\"Misfire Management\",\"value\":\"Experienced personnel to support the assessment, management and controlled resolution of misfires.\",\"overview\":[\"Misfires can create complex safety and operational challenges that aren't always resolved in a single shift.\",\"TEXC provides experienced personnel to support the assessment, management and controlled resolution of suspected or confirmed misfires, working alongside site management and existing blasting teams.\"],\"capabilities\":[\"Assessment support\",\"Controlled resolution\",\"Suspected and confirmed events\",\"Multi-shift and multi-day management\",\"Dedicated personnel for extended events\",\"Independent documentation and reporting\"],\"integrate\":\"TEXC works alongside site management and your existing blasting team, within your systems, procedures and inductions. Scope and availability are confirmed on enquiry.\",\"safety\":\"Misfire management is directed by site management and carried out under your procedures, risk assessment and applicable legislative requirements. Procedural detail is managed with your site rather than published. If you are dealing with an active misfire, call TEXC on 0467 651 182 — an enquiry form is not an emergency channel, and engagement does not guarantee immediate availability.\",\"pending\":false},{\"slug\":\"magazine-management\",\"name\":\"Magazine Management\",\"category\":\"Magazine Management\",\"value\":\"Professional magazine management and inventory control.\",\"overview\":[\"Magazine management is about accurate records, compliant storage and reliable reconciliation. TEXC provides experienced support to keep inventory controlled and documented.\",\"We handle the administrative and compliance side so your explosives records stay accurate and audit-ready.\"],\"capabilities\":[\"Stock management\",\"Inventory reconciliation\",\"Compliance\",\"Documentation\",\"Magazine inspections\"],\"integrate\":\"TEXC works within your compliance framework and procedures, providing magazine management support that keeps records accurate and reconciled.\",\"safety\":\"For security reasons, TEXC does not publish magazine locations, stock levels, access procedures or inventory information. All work is handled under appropriate controls.\",\"pending\":false},{\"slug\":\"magazine-staging\",\"name\":\"Magazine Staging\",\"category\":\"Magazine Staging & Storage\",\"value\":\"Secure staging and temporary explosives management for projects.\",\"overview\":[\"Projects sometimes need explosives staged securely for a defined period. TEXC provides temporary staging and management support, coordinated with your project requirements.\",\"Availability is confirmed on enquiry and managed under appropriate controls.\"],\"capabilities\":[\"Project staging\",\"Temporary storage\",\"Client support\",\"Inventory management\",\"Magazine access\"],\"integrate\":\"TEXC coordinates staging around your project timeline and requirements, managed under appropriate controls and confirmed on enquiry.\",\"safety\":\"TEXC does not imply unlimited capacity or public access. Storage availability is configurable, confirmed on enquiry, and subject to approval and applicable requirements.\",\"pending\":false},{\"slug\":\"explosives-logistics\",\"name\":\"Explosives Logistics\",\"category\":\"Explosives Logistics\",\"value\":\"Safe movement of explosives and accessories, with full transfer documentation.\",\"overview\":[\"Getting explosives and accessories to site safely and compliantly is a specialist task. TEXC supports project supply with proper documentation and coordination.\",\"We manage the paperwork and coordination so the right materials arrive where they are needed.\"],\"capabilities\":[\"Deliveries\",\"Transfer documentation\",\"Manifest management\",\"Magazine transfers\",\"Project supply\"],\"integrate\":\"TEXC coordinates logistics with your project schedule and site requirements, handling transfer documentation and manifests so supply stays compliant.\",\"safety\":\"For security reasons, TEXC does not publish transport routes, schedules, quantities, vehicle details or storage destinations. Generic imagery does not imply ownership of vehicles or equipment.\",\"pending\":false},{\"slug\":\"industrial-services\",\"name\":\"Industrial Services\",\"category\":\"Industrial Services\",\"value\":\"Supporting industrial projects requiring specialist blasting capability.\",\"overview\":[\"Industrial projects and plant shutdowns sometimes need specialist blasting capability for a defined scope. TEXC provides that support, coordinated with your maintenance and operations teams.\",\"We work within your site requirements and schedule, providing specialist blasting capability where and when it's needed.\"],\"capabilities\":[\"Manufacturing support\",\"Plant shutdowns\",\"Industrial maintenance\",\"Specialist blasting\"],\"integrate\":\"TEXC coordinates with your shutdown program and industrial site controls, providing specialist capability for the defined scope and window.\",\"safety\":\"Work is planned to project-specific risk assessment and your site procedures, subject to approvals and applicable requirements.\",\"pending\":false},{\"slug\":\"mpu-support\",\"name\":\"MPU Support\",\"category\":\"MPU Support\",\"value\":\"Additional personnel to support production operations.\",\"overview\":[\"Production operations sometimes need extra experienced hands on the bench. TEXC supplies personnel to support loading, preparation and explosives management.\",\"We integrate with your production crew and systems for the period you need.\"],\"capabilities\":[\"Bench support\",\"Loading assistance\",\"Explosives management\",\"Blast preparation\"],\"integrate\":\"TEXC provides personnel who integrate with your production operation, systems and inductions. The specific offering — personnel, equipment or both — is confirmed on enquiry.\",\"safety\":\"All work follows your site procedures, risk assessment and applicable requirements. TEXC supplies experienced personnel; equipment provision is confirmed on enquiry.\",\"pending\":false},{\"slug\":\"remote-operations\",\"name\":\"Remote Area Operations\",\"category\":\"Remote Area Operations\",\"value\":\"Support for difficult-to-access sites — capability currently in development.\",\"overview\":[\"TEXC is scoping support for remote and difficult-to-access projects. This is not a service TEXC delivers today, and nothing on this page should be read as a current capability, licence or approval.\",\"If you have work coming up somewhere hard to reach, tell us about it. Early visibility on real projects is what shapes where this goes and how quickly.\"],\"capabilities\":[],\"integrate\":\"\",\"safety\":\"No remote area capability is offered or implied at this stage. TEXC does not imply ownership of aircraft or specialist transport, and does not publish remote magazine or project coordinates. Any future work would be subject to the licences, approvals and site procedures applicable to it, confirmed before anything is agreed.\",\"pending\":true},{\"slug\":\"marine-coastal\",\"name\":\"Marine & Coastal\",\"category\":\"Marine & Coastal\",\"value\":\"Marine and coastal blasting support — capability currently in development.\",\"overview\":[\"TEXC is scoping marine and coastal blasting support. This is not a service TEXC delivers today, and nothing on this page should be read as a current capability, licence or approval.\",\"If you have a coastal or marine requirement coming up, tell us about it. Early visibility on real projects is what shapes where this goes and how quickly.\"],\"capabilities\":[],\"integrate\":\"\",\"safety\":\"No marine or coastal capability is offered or implied at this stage. Any future work would be subject to the licences, approvals and site procedures applicable to it, confirmed before anything is agreed.\",\"pending\":true}],\"serviceIcons\":{\"relief-shotfiring\":\"zap\",\"civil-construction\":\"mountain\",\"quarry-mining\":\"layers\",\"microblasting\":\"crosshair\",\"shot-sleeping\":\"moon\",\"misfire-management\":\"alert-circle\",\"magazine-management\":\"box\",\"magazine-staging\":\"archive\",\"explosives-logistics\":\"truck\",\"industrial-services\":\"factory\",\"mpu-support\":\"users\",\"remote-operations\":\"map-pin\",\"marine-coastal\":\"map-pin\"},\"people\":[{\"slug\":\"george-scott\",\"name\":\"George Scott\",\"role\":\"Managing Director | Licensed Shotfirer\",\"bio\":[\"George Scott is the founder and Managing Director of TEXC and a licensed shotfirer with hands-on experience across quarrying, civil construction, mining and specialist blasting operations.\",\"Having worked across both large-scale operations and smaller specialist projects, George established TEXC with a practical understanding of how blasting operations work in the field and where additional capability can make a difference.\",\"He remains actively involved in TEXC’s field operations while leading the continued development of the business, its systems and its approach to specialist blasting services.\"],\"competencies\":[\"RIIBLA201E Support Shotfiring Operations\",\"RIIBLA205E Store, Handle & Transport Explosives\",\"RIIBLA301E Conduct Surface Shotfiring Operations\",\"RIIBLA305E Conduct Secondary Blasting\",\"RIIBLA401 Manage Blasting Operations\",\"RIIBLA402 Monitor & Control the Effects of Blasting on the Environment\",\"RIIPLA403 Design Blasts\",\"RIIBHD301D Conduct Surface Blast Hole Drilling Operations\",\"RIIRIS301E Apply Risk Management Processes\",\"RIICOM301E Communicate Information\",\"RIIWHS301E Conduct Health & Safety Investigations\"],\"licences\":[\"TLILIC0001 Licence to Transport Dangerous Goods by Road\",\"TLILIC2001A Licence to Operate a Forklift Truck\",\"TLILIC3017 Licence to Drive a Heavy Combination Vehicle\"],\"licenceNote\":\"Copies are provided as supporting documentation on request. Nothing is listed here until it has been sighted and is current.\"}],\"regions\":[\"Northern Tasmania\",\"Southern Tasmania\",\"North-West Tasmania\",\"East Coast Tasmania\",\"West Coast Tasmania\",\"Statewide / multiple\"],\"register\":[{\"id\":\"TEXC01\",\"title\":\"Civil Shotfiring Risk & Compliance Tool\",\"code\":\"TEXC-FRA-BLAST-003\",\"category\":\"Risk & Compliance\",\"status\":\"approved\"},{\"id\":\"TEXC02\",\"title\":\"Shotfiring Risk & Compliance Tool (quarry & mining)\",\"code\":\"TEXC-FRA-BLAST-002\",\"category\":\"Risk & Compliance\",\"status\":\"approved\"},{\"id\":\"TEXC03\",\"title\":\"Explosive Security Risk & Compliance Tool (shot sleeping)\",\"code\":\"TEXC-FRA-SLEEP-001\",\"category\":\"Risk & Compliance\",\"status\":\"approved\"},{\"id\":\"TEXC04\",\"title\":\"Load Manifest\",\"code\":\"TEXC-SMS-FRM-012\",\"category\":\"Logistics & Registers\",\"status\":\"approved\"},{\"id\":\"TEXC05\",\"title\":\"Magazine Key Register\",\"code\":\"\",\"category\":\"Logistics & Registers\",\"status\":\"approved\"},{\"id\":\"TEXC06\",\"title\":\"Magazine Record Book\",\"code\":\"\",\"category\":\"Logistics & Registers\",\"status\":\"approved\"},{\"id\":\"TEXC07\",\"title\":\"Blast Report\",\"code\":\"\",\"category\":\"Reports\",\"status\":\"approved\"},{\"id\":\"TEXC08\",\"title\":\"Explosive Security Report\",\"code\":\"\",\"category\":\"Reports\",\"status\":\"approved\"},{\"id\":\"TEXC09\",\"title\":\"Misfire Risk & Compliance Tool\",\"code\":\"TEXC-FRA-MISFIRE-002\",\"category\":\"Risk & Compliance\",\"status\":\"approved\"},{\"id\":\"TEXC10\",\"title\":\"Incident Report\",\"code\":\"TEXC-SMS-FRM-013\",\"category\":\"Statements\",\"status\":\"approved\"},{\"id\":\"TEXC11\",\"title\":\"Timing Variation Activity Statement\",\"code\":\"TEXC-SVF-FRM-001\",\"category\":\"Statements\",\"status\":\"approved\"},{\"id\":\"TEXC12\",\"title\":\"Misfire Report\",\"code\":\"\",\"category\":\"Reports\",\"status\":\"draft\"}],\"workflow\":{\"intro\":\"Every blasting project follows a structured process to ensure explosives remain fully accounted for from the moment they leave the magazine until the project is complete.\",\"stages\":[{\"n\":1,\"title\":\"Magazine Inventory\",\"line\":\"The process begins at the explosives magazine.\"},{\"n\":2,\"title\":\"Transfer Note / Manifest\",\"line\":\"The explosives are then transferred onto a Transfer Note (Manifest).\"},{\"n\":3,\"title\":\"Site Risk Assessment\",\"line\":\"Before any explosives are loaded, a project-specific Risk Assessment is completed.\"},{\"n\":4,\"title\":\"Charging Operations\",\"line\":\"Explosives are loaded into the blast in accordance with the blast design and project requirements.\"},{\"n\":5,\"title\":\"Transfer Note Reconciliation\",\"line\":\"Once charging has been completed, the Transfer Note is reconciled.\"},{\"n\":6,\"title\":\"Magazine Inventory Reconciliation\",\"line\":\"Any unused explosives or accessories are returned to the magazine.\"},{\"n\":7,\"title\":\"Blast Monitoring\",\"line\":\"The blast is fired.\"},{\"n\":8,\"title\":\"Blast Report\",\"line\":\"The final Blast Report is then prepared.\"}]},\"photos\":{\"bulk-earthworks\":{\"widths\":[800,1400],\"path\":\"/assets/img/photos/bulk-earthworks-{w}.webp\"},\"civil-excavator\":{\"widths\":[800,1315],\"path\":\"/assets/img/photos/civil-excavator-{w}.webp\"},\"george-scott\":{\"widths\":[800,1080],\"path\":\"/assets/img/photos/george-scott-{w}.webp\"},\"initiation-detail\":{\"widths\":[800,1400],\"path\":\"/assets/img/photos/initiation-detail-{w}.webp\"},\"quarry-dusk-wide\":{\"widths\":[800,1600,1902],\"path\":\"/assets/img/photos/quarry-dusk-wide-{w}.webp\"},\"quarry-tie-in\":{\"widths\":[800,1400],\"path\":\"/assets/img/photos/quarry-tie-in-{w}.webp\"},\"rock-face-water\":{\"widths\":[800,1400],\"path\":\"/assets/img/photos/rock-face-water-{w}.webp\"},\"texc-ute-forestry\":{\"widths\":[800,1400],\"path\":\"/assets/img/photos/texc-ute-forestry-{w}.webp\"}},\"principalPhoto\":\"george-scott\",\"ratingsEnabled\":false}</script>\n<script type=\"module\" src=\"/assets/js/proposal.js\"></script>\n<script type=\"module\" src=\"/assets/js/archive-view.js\"></script>\n</head>\n<body>\n<div id=\"gate\" class=\"gate\" role=\"main\" hidden>\n  <div class=\"gate-card\" data-gate=\"form\">\n    <img class=\"gate-logo\" src=\"/assets/img/logo/TEXC-Gold.svg\" alt=\"TEXC\" width=\"132\" height=\"52\">\n    <p class=\"gate-eyebrow\">Private proposal</p>\n    <h2 class=\"gate-title\" id=\"gate-title\">Enter your passphrase</h2>\n    <form class=\"gate-form\" id=\"gate-form\" autocomplete=\"off\" novalidate>\n      <label class=\"gate-label\" for=\"gate-pass\">Passphrase</label>\n      <input class=\"gate-input\" id=\"gate-pass\" name=\"passphrase\" type=\"password\" autocomplete=\"off\" autocapitalize=\"none\" autocorrect=\"off\" spellcheck=\"false\" required aria-describedby=\"gate-msg gate-help\">\n      <label class=\"gate-show\"><input type=\"checkbox\" id=\"gate-show\"> Show passphrase</label>\n      <button type=\"submit\" class=\"btn btn--primary btn--lg gate-go\" id=\"gate-go\">Open the proposal</button>\n      <p class=\"gate-msg\" id=\"gate-msg\" role=\"alert\" aria-live=\"assertive\"></p>\n    </form>\n    <p class=\"gate-help\" id=\"gate-help\">TEXC gives you the passphrase separately, by phone or text message. If you do not have it, call George Scott on <a href=\"tel:0467651182\">0467 651 182</a>.</p>\n  </div>\n  <div class=\"gate-card\" data-gate=\"gone\" hidden>\n    <img class=\"gate-logo\" src=\"/assets/img/logo/TEXC-Gold.svg\" alt=\"TEXC\" width=\"132\" height=\"52\">\n    <p class=\"gate-eyebrow\">Private proposal</p>\n    <h2 class=\"gate-title\">This link is no longer active</h2>\n    <p class=\"gate-help\">The proposal may have been replaced, withdrawn or reached its expiry date. For the current link, call George Scott on <a href=\"tel:0467651182\">0467 651 182</a> or email <a href=\"mailto:management@texc.au\">management@texc.au</a>.</p>\n  </div>\n  <div class=\"gate-card\" data-gate=\"wait\" hidden>\n    <img class=\"gate-logo\" src=\"/assets/img/logo/TEXC-Gold.svg\" alt=\"TEXC\" width=\"132\" height=\"52\">\n    <p class=\"gate-help\" data-gate-wait>Loading…</p>\n  </div>\n</div>\n<noscript><p class=\"gate-noscript\">This proposal needs JavaScript switched on to open.</p></noscript>\n<a class=\"skip\" href=\"#main\">Skip to the proposal</a>\n\n<div id=\"pbar\" class=\"pbar\" aria-hidden=\"true\"><span></span></div>\n\n<div id=\"staff-strip\" class=\"staff-strip\" role=\"region\" aria-label=\"About this revision\" hidden></div>\n<header id=\"topbar\" class=\"topbar\">\n  <div class=\"topbar-in\">\n    <a class=\"topbar-logo\" href=\"#cover\" aria-label=\"Back to the cover\">\n      <img src=\"/assets/img/logo/TEXC-Gold.svg\" alt=\"TEXC\" width=\"102\" height=\"40\">\n    </a>\n    <span class=\"topbar-rule\" aria-hidden=\"true\"></span>\n    <div class=\"topbar-title\">\n      <span class=\"topbar-project\" data-field=\"meta.project\" data-empty=\"\"></span>\n      <span class=\"topbar-for\">Prepared for <span data-field=\"client.company\" data-empty=\"\"></span></span>\n    </div>\n    <div class=\"topbar-actions\">\n      <span class=\"chip\" data-status-chip><span class=\"chip-dot\" aria-hidden=\"true\"></span><span data-field=\"meta.statusLabel\" data-empty=\"\"></span></span>\n      <button type=\"button\" class=\"btn btn--secondary btn--sm topbar-print\" data-print>\n        <svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#printer\"/></svg><span>Download PDF</span>\n      </button>\n      <button type=\"button\" class=\"btn btn--secondary btn--sm topbar-sections\" id=\"index-toggle\" aria-controls=\"sheet\" aria-expanded=\"false\">\n        <svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#list\"/></svg><span>Sections</span>\n      </button>\n    </div>\n  </div>\n</header>\n\n<div id=\"demo-chip\" class=\"demo-chip\" hidden>Demo — fictional client and site</div>\n\n<div id=\"superseded\" class=\"superseded\" role=\"status\" hidden>\n  <div class=\"wrap superseded-in\">\n    <svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#alert-triangle\"/></svg>\n    <p>This revision has been superseded by Rev <span data-field=\"meta.supersededBy\" data-empty=\"\"></span>.\n      <a data-current-link href=\"#\" hidden>View the current proposal</a></p>\n  </div>\n</div>\n\n<nav id=\"index\" class=\"rail\" aria-label=\"Proposal sections\">\n  <ol data-index-list></ol>\n</nav>\n\n<div id=\"sheet\" class=\"sheet\" hidden>\n  <div class=\"sheet-scrim\" data-sheet-close></div>\n  <div class=\"sheet-panel\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"sheet-title\">\n    <div class=\"sheet-head\">\n      <p id=\"sheet-title\" class=\"label\">Sections</p>\n      <button type=\"button\" class=\"icon-btn\" data-sheet-close aria-label=\"Close sections\">\n        <svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#x\"/></svg>\n      </button>\n    </div>\n    <ol class=\"sheet-list\" data-sheet-list></ol>\n  </div>\n</div>\n\n<main id=\"main\" tabindex=\"-1\">\n\n<!-- 01 COVER ============================================================ -->\n<section id=\"cover\" class=\"sec cover\" data-sec=\"cover\" data-label=\"Cover\" data-surface=\"ink\">\n  <div class=\"cover-media\">\n    <img data-img=\"cover.image\" alt=\"\" sizes=\"100vw\" fetchpriority=\"high\">\n  </div>\n  <div class=\"cover-scrim\" aria-hidden=\"true\"></div>\n  <div class=\"wrap cover-in\">\n    <div class=\"cover-kicker\" data-reveal>\n      <span class=\"cover-lean\" aria-hidden=\"true\"></span>\n      <span class=\"label label--gold\" data-field=\"meta.docTypeLabel\" data-empty=\"Shotfiring Proposal\">Shotfiring Proposal</span>\n    </div>\n    <h1 class=\"cover-title\" data-reveal><span data-field=\"meta.project\" data-empty=\"\"></span></h1>\n    <p class=\"cover-site\" data-reveal>\n      <svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#map-pin\"/></svg>\n      <span data-field=\"meta.siteLine\" data-empty=\"\"></span>\n    </p>\n    <dl class=\"cover-meta\" data-reveal>\n      <div class=\"cover-meta-for\"><dt>Prepared for</dt><dd><span data-field=\"client.company\" data-empty=\"\"></span><span class=\"cover-contact\" data-field=\"client.contactLine\" data-empty=\"\"></span></dd></div>\n      <div><dt>Reference</dt><dd data-field=\"meta.reference\" data-empty=\"Allocated on issue\">Allocated on issue</dd></div>\n      <div><dt>Revision</dt><dd data-field=\"meta.revLabel\" data-empty=\"—\">—</dd></div>\n      <div><dt>Issued</dt><dd data-field=\"meta.issueDateText\" data-empty=\"—\">—</dd></div>\n      <div><dt>Valid until</dt><dd data-field=\"meta.validUntilText\" data-empty=\"—\">—</dd></div>\n      <div><dt>Prepared by</dt><dd data-field=\"meta.preparedBy\" data-empty=\"George Scott\">George Scott</dd></div>\n    </dl>\n    <div class=\"cover-actions\" data-reveal>\n      <a class=\"btn btn--primary btn--lg btn--glow\" href=\"#accept\">Review and accept</a>\n      <a class=\"btn btn--secondary btn--lg\" href=\"#quote\">View the quotation</a>\n    </div>\n  </div>\n  <p class=\"cover-credit\" data-field=\"cover.image.credit\" data-empty=\"\"></p>\n</section>\n\n<!-- 02 COVERING LETTER ================================================== -->\n<section id=\"letter\" class=\"sec\" data-sec=\"letter\" data-label=\"Covering letter\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Covering letter</h2></div>\n    <div class=\"letter\">\n      <div class=\"letter-body\" data-reveal>\n        <p class=\"letter-greet\">Dear <span data-field=\"letter.greetingName\" data-empty=\"\"></span>,</p>\n        <div class=\"prose\" data-paras=\"letter.body\"></div>\n        <div class=\"letter-sign\">\n          <p>Regards,</p>\n          <p class=\"letter-name\" data-field=\"letter.signoffName\" data-empty=\"George Scott\">George Scott</p>\n          <p class=\"letter-role\" data-field=\"letter.signoffRole\" data-empty=\"Managing Director | Licensed Shotfirer\">Managing Director | Licensed Shotfirer</p>\n          <p class=\"letter-entity\">TEXC Pty Ltd</p>\n        </div>\n      </div>\n      <figure class=\"letter-portrait\" data-reveal data-hide-empty=\"letter.portrait\">\n        <img data-img=\"letter.portrait\" alt=\"\" sizes=\"(max-width: 900px) 40vw, 300px\" loading=\"lazy\">\n      </figure>\n    </div>\n  </div>\n</section>\n\n<!-- 03 AT A GLANCE ====================================================== -->\n<section id=\"glance\" class=\"sec\" data-sec=\"glance\" data-label=\"Proposal at a glance\" data-surface=\"ink\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Proposal at a glance</h2></div>\n    <dl class=\"glance\" data-reveal>\n      <div class=\"glance-cell glance-cell--wide\"><dt>Services</dt><dd data-field=\"glance.services\" data-empty=\"—\">—</dd></div>\n      <div class=\"glance-cell glance-cell--wide\"><dt>Site</dt><dd data-field=\"meta.siteLine\" data-empty=\"—\">—</dd></div>\n      <div class=\"glance-cell\"><dt>Proposed start</dt><dd data-field=\"glance.start\" data-empty=\"—\">—</dd></div>\n      <div class=\"glance-cell\"><dt>Estimated duration</dt><dd data-field=\"glance.duration\" data-empty=\"—\">—</dd></div>\n      <div class=\"glance-cell\"><dt>Mobilisation lead time</dt><dd data-field=\"glance.leadTime\" data-empty=\"—\">—</dd></div>\n      <div class=\"glance-cell\"><dt>Valid until</dt><dd data-field=\"meta.validUntilText\" data-empty=\"—\">—</dd></div>\n      <div class=\"glance-cell glance-cell--total\"><dt>Total ex GST</dt><dd><span data-field=\"quote.subtotalText\" data-empty=\"—\" data-live>—</span><small data-field=\"quote.atCostNote\" data-empty=\"\"></small></dd></div>\n      <div class=\"glance-cell glance-cell--holds\"><dt>Hold points outstanding</dt><dd><span class=\"dot dot--caution\" aria-hidden=\"true\"></span><span data-field=\"glance.holds\" data-empty=\"—\">—</span></dd></div>\n    </dl>\n    <div class=\"glance-cta\" data-reveal>\n      <p>Read through each section, tick any optional items in the quotation, then accept online. Accepting permits planning and site preparation only.</p>\n      <div class=\"glance-cta-actions\">\n        <a class=\"btn btn--primary btn--lg\" href=\"#accept\">Go to acceptance <svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#arrow-down\"/></svg></a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 04 ABOUT ============================================================ -->\n<section id=\"about\" class=\"sec\" data-sec=\"about\" data-label=\"About TEXC\" data-surface=\"raised\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">About TEXC</h2></div>\n    <div class=\"about\" data-reveal>\n      <div>\n        <p class=\"kicker\" data-field=\"about.support.heading\" data-empty=\"Built to support established contractors.\">Built to support established contractors.</p>\n        <p class=\"body-lg\" data-field=\"about.support.body\" data-empty=\"Rather than competing against established blasting contractors, TEXC was built to support them — integrating into existing operations for a single day or the long term, working within your systems or approved TEXC procedures.\">Rather than competing against established blasting contractors, TEXC was built to support them — integrating into existing operations for a single day or the long term, working within your systems or approved TEXC procedures.</p>\n      </div>\n      <blockquote class=\"about-quote\">\n        <p data-field=\"about.support.quote\" data-empty=\"We don't see other blasting contractors as competitors. We see them as potential clients and project partners.\">We don't see other blasting contractors as competitors. We see them as potential clients and project partners.</p>\n        <footer>George Scott — TEXC Pty Ltd</footer>\n      </blockquote>\n    </div>\n    <ul class=\"strip\" data-rows=\"about.strip\" data-rows-default data-reveal>\n      <li data-row><span class=\"strip-label\" data-col=\"label\">Flexible support</span><span class=\"strip-body\" data-col=\"body\">Relief cover, peak workloads and short-notice capability.</span></li>\n      <li data-row><span class=\"strip-label\" data-col=\"label\">Site integration</span><span class=\"strip-body\" data-col=\"body\">We work within your systems, people and procedures.</span></li>\n      <li data-row><span class=\"strip-label\" data-col=\"label\">Specialist capability</span><span class=\"strip-body\" data-col=\"body\">Shotfiring, logistics and magazine support in one source.</span></li>\n      <li data-row><span class=\"strip-label\" data-col=\"label\">Safety &amp; compliance</span><span class=\"strip-body\" data-col=\"body\">Risk assessment, documentation and legislative compliance.</span></li>\n      <li data-row><span class=\"strip-label\" data-col=\"label\">Tasmania wide</span><span class=\"strip-body\" data-col=\"body\">Supporting projects across the state, including remote sites.</span></li>\n    </ul>\n    <p class=\"label about-steps-label\" data-reveal data-field=\"about.working.heading\" data-empty=\"What it should feel like.\">What it should feel like.</p>\n    <ol class=\"steps4\" data-rows=\"about.steps\" data-rows-default data-reveal>\n      <li data-row><span class=\"steps4-n\" data-col=\"number\">01</span><span class=\"steps4-title\" data-col=\"title\">Straightforward</span><span class=\"steps4-body\" data-col=\"body\">Easy to engage, with a clear path from enquiry to work on site.</span></li>\n      <li data-row><span class=\"steps4-n\" data-col=\"number\">02</span><span class=\"steps4-title\" data-col=\"title\">Responsive</span><span class=\"steps4-body\" data-col=\"body\">We work to keep communication clear and lead times short.</span></li>\n      <li data-row><span class=\"steps4-n\" data-col=\"number\">03</span><span class=\"steps4-title\" data-col=\"title\">Professional</span><span class=\"steps4-body\" data-col=\"body\">Considered planning, documentation and compliance on every job.</span></li>\n      <li data-row><span class=\"steps4-n\" data-col=\"number\">04</span><span class=\"steps4-title\" data-col=\"title\">Practical</span><span class=\"steps4-body\" data-col=\"body\">Real support that fits how your project actually runs.</span></li>\n    </ol>\n  </div>\n</section>\n\n<!-- 05 PROJECT UNDERSTANDING ============================================ -->\n<section id=\"understanding\" class=\"sec\" data-sec=\"understanding\" data-label=\"Project understanding\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Project understanding</h2></div>\n    <div class=\"prose prose--wide\" data-paras=\"understanding.paras\" data-reveal></div>\n    <div class=\"figs\" data-rows=\"understanding.photos\" data-hide-empty=\"understanding.photos\">\n      <figure class=\"fig\" data-row data-reveal>\n        <div class=\"fig-img\"><img data-col-img=\"image\" alt=\"\" sizes=\"(max-width: 640px) 100vw, (max-width: 1180px) 50vw, 380px\" loading=\"lazy\"></div>\n        <figcaption>\n          <span class=\"fig-title\" data-col=\"title\"></span>\n          <span class=\"fig-caption\" data-col=\"caption\"></span>\n          <span class=\"fig-credit\" data-col=\"credit\"></span>\n        </figcaption>\n      </figure>\n    </div>\n    <figure class=\"plan\" data-hide-empty=\"understanding.sitePlan\" data-reveal>\n      <div class=\"plan-img\">\n        <img data-img=\"understanding.sitePlan\" alt=\"\" sizes=\"(max-width: 1240px) 100vw, 1152px\" loading=\"lazy\">\n        <span class=\"plan-label\" data-locked=\"sitePlanLabel\"></span>\n      </div>\n      <figcaption data-field=\"understanding.sitePlan.caption\" data-empty=\"\"></figcaption>\n    </figure>\n    <aside class=\"callout\" data-hide-empty=\"understanding.callout\" data-reveal>\n      <p><strong data-field=\"understanding.callout.lead\" data-empty=\"\"></strong> <span data-field=\"understanding.callout.text\" data-empty=\"\"></span></p>\n    </aside>\n  </div>\n</section>\n\n<!-- 06 SCOPE OF WORKS =================================================== -->\n<section id=\"scope\" class=\"sec\" data-sec=\"scope\" data-label=\"Scope of works\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Scope of works</h2></div>\n    <div class=\"services\" data-rows=\"scope.services\">\n      <article class=\"svc\" data-row data-reveal>\n        <div class=\"svc-head\">\n          <span class=\"svc-ic\" aria-hidden=\"true\"><svg class=\"ic\"><use data-col-icon=\"icon\" href=\"/assets/img/icons.svg#hard-hat\"/></svg></span>\n          <div><p class=\"label label--paper\" data-col=\"category\"></p><h3 class=\"h3\" data-col=\"name\"></h3></div>\n        </div>\n        <div class=\"prose\" data-col-paras=\"scopeText\"></div>\n        <p class=\"svc-safety\"><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#shield-check\"/></svg><span data-col=\"safety\"></span></p>\n      </article>\n    </div>\n    <div class=\"incl\" data-reveal>\n      <div data-hide-empty=\"scope.inclusions\">\n        <h3 class=\"h4\">Included</h3>\n        <ul class=\"ticks\" data-list=\"scope.inclusions\"><li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#check\"/></svg><span data-item></span></li></ul>\n      </div>\n      <div data-hide-empty=\"scope.exclusions\">\n        <h3 class=\"h4\">Not included</h3>\n        <ul class=\"ticks ticks--minus\" data-list=\"scope.exclusions\"><li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#minus\"/></svg><span data-item></span></li></ul>\n      </div>\n    </div>\n    <div class=\"block\" data-hide-empty=\"scope.matrix\" data-reveal>\n      <h3 class=\"h4\">Who is responsible for what</h3>\n      <div class=\"tbl-wrap\">\n        <table class=\"tbl tbl--matrix\">\n          <thead><tr><th scope=\"col\">Item</th><th scope=\"col\">TEXC</th><th scope=\"col\">Client</th><th scope=\"col\">Shared</th><th scope=\"col\">Notes</th></tr></thead>\n          <tbody data-rows=\"scope.matrix\">\n            <tr data-row>\n              <th scope=\"row\" class=\"term\" data-col=\"item\"></th>\n              <td class=\"mark\" data-mark=\"texc\" data-label=\"TEXC\"></td>\n              <td class=\"mark\" data-mark=\"client\" data-label=\"Client\"></td>\n              <td class=\"mark\" data-mark=\"shared\" data-label=\"Shared\"></td>\n              <td class=\"note\" data-col=\"note\" data-label=\"Notes\"></td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <p class=\"fineprint\" data-snap=\"scopeNote\" data-reveal></p>\n  </div>\n</section>\n\n<!-- 07 SITE DETAILS AND CONSTRAINTS ===================================== -->\n<section id=\"site\" class=\"sec\" data-sec=\"site\" data-label=\"Site details and constraints\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Site details and constraints</h2></div>\n    <dl class=\"meta-grid\" data-rows=\"site.meta\" data-reveal>\n      <div data-row><dt data-col=\"label\"></dt><dd data-col=\"value\"></dd></div>\n    </dl>\n    <div class=\"block\" data-hide-empty=\"site.conditions\" data-reveal>\n      <h3 class=\"h4\">Identified site conditions</h3>\n      <ul class=\"diamonds\" data-list=\"site.conditions\"><li data-item></li></ul>\n    </div>\n    <div class=\"figs\" data-rows=\"site.photos\" data-hide-empty=\"site.photos\">\n      <figure class=\"fig\" data-row data-reveal>\n        <div class=\"fig-img\"><img data-col-img=\"image\" alt=\"\" sizes=\"(max-width: 640px) 100vw, (max-width: 1180px) 50vw, 380px\" loading=\"lazy\"></div>\n        <figcaption><span class=\"fig-title\" data-col=\"title\"></span><span class=\"fig-caption\" data-col=\"caption\"></span><span class=\"fig-credit\" data-col=\"credit\"></span></figcaption>\n      </figure>\n    </div>\n    <div class=\"block\" data-hide-empty=\"site.constraints\" data-reveal>\n      <h3 class=\"h4\">Constraints and control intent</h3>\n      <div class=\"tbl-wrap\">\n        <table class=\"tbl\">\n          <thead><tr><th scope=\"col\">Constraint</th><th scope=\"col\">Control intent</th></tr></thead>\n          <tbody data-rows=\"site.constraints\"><tr data-row><th scope=\"row\" class=\"term\" data-col=\"constraint\"></th><td data-col=\"intent\" data-label=\"Control intent\"></td></tr></tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 08 PROPOSED WORK PROCESS ============================================ -->\n<section id=\"method\" class=\"sec\" data-sec=\"method\" data-label=\"Proposed work process\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Proposed work process</h2></div>\n    <p class=\"body-lg prose--wide\" data-field=\"method.intro\" data-empty=\"\" data-reveal></p>\n    <ol class=\"process\" data-rows=\"method.steps\">\n      <li class=\"process-step\" data-row data-reveal>\n        <span class=\"process-n\" data-col-index aria-hidden=\"true\"></span>\n        <div><h3 class=\"process-title\" data-col=\"title\"></h3><p data-col=\"detail\"></p></div>\n      </li>\n    </ol>\n    <div data-rows=\"method.callouts\">\n      <aside class=\"callout\" data-row data-reveal><p><strong data-col=\"lead\"></strong> <span data-col=\"text\"></span></p></aside>\n    </div>\n  </div>\n</section>\n\n<!-- 09 PRELIMINARY BLAST PARAMETERS (off by default) ==================== -->\n<section id=\"params\" class=\"sec\" data-sec=\"params\" data-label=\"Preliminary blast parameters\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Preliminary blast parameters</h2></div>\n    <aside class=\"notice notice--caution\" data-reveal><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#alert-triangle\"/></svg><p data-locked=\"paramsLine\"></p></aside>\n    <div class=\"tbl-wrap\" data-reveal>\n      <table class=\"tbl tbl--params\">\n        <thead><tr><th scope=\"col\">Parameter</th><th scope=\"col\">Preliminary value</th></tr></thead>\n        <tbody data-params></tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- 10 VIBRATION, OVERPRESSURE AND ENVIRONMENTAL MANAGEMENT ============= -->\n<section id=\"env\" class=\"sec\" data-sec=\"env\" data-label=\"Vibration, overpressure and environment\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Vibration, overpressure and environmental management</h2></div>\n    <div class=\"cols2\">\n      <div class=\"block\" data-hide-empty=\"env.monitoring\" data-reveal>\n        <h3 class=\"h4\">Monitoring approach</h3>\n        <p data-field=\"env.monitoring\" data-empty=\"\"></p>\n      </div>\n      <div class=\"block\" data-hide-empty=\"env.locations\" data-reveal>\n        <h3 class=\"h4\">Monitoring locations</h3>\n        <ul class=\"diamonds\" data-list=\"env.locations\"><li data-item></li></ul>\n      </div>\n    </div>\n    <div class=\"block\" data-reveal>\n      <h3 class=\"h4\">Limits</h3>\n      <aside class=\"notice\"><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#info\"/></svg><p data-locked=\"envLimitsNote\"></p></aside>\n      <div class=\"tbl-wrap\" data-hide-empty=\"env.limits.rows\">\n        <table class=\"tbl\">\n          <thead><tr><th scope=\"col\">Parameter</th><th scope=\"col\">Limit</th><th scope=\"col\">Source</th></tr></thead>\n          <tbody data-rows=\"env.limits.rows\"><tr data-row><th scope=\"row\" class=\"term\" data-col=\"parameter\"></th><td data-col=\"limit\" data-label=\"Limit\"></td><td data-col=\"source\" data-label=\"Source\"></td></tr></tbody>\n        </table>\n      </div>\n      <p class=\"fineprint\" data-field=\"env.limits.pending\" data-empty=\"\"></p>\n    </div>\n    <div class=\"block\" data-hide-empty=\"env.controls\" data-reveal>\n      <h3 class=\"h4\">Flyrock, dust and noise controls</h3>\n      <div class=\"tbl-wrap\">\n        <table class=\"tbl\">\n          <thead><tr><th scope=\"col\">Effect</th><th scope=\"col\">Control</th></tr></thead>\n          <tbody data-rows=\"env.controls\"><tr data-row><th scope=\"row\" class=\"term\" data-col=\"topic\"></th><td data-col=\"text\" data-label=\"Control\"></td></tr></tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"block\" data-hide-empty=\"env.neighbours\" data-reveal>\n      <h3 class=\"h4\">Neighbour notification</h3>\n      <p data-field=\"env.neighbours\" data-empty=\"\"></p>\n    </div>\n  </div>\n</section>\n\n<!-- 11 SAFETY, RISK AND COMPLIANCE ====================================== -->\n<section id=\"risk\" class=\"sec\" data-sec=\"risk\" data-label=\"Safety, risk and compliance\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Safety, risk and compliance</h2></div>\n    <div class=\"prose prose--wide\" data-paras=\"risk.intro\" data-reveal></div>\n    <aside class=\"notice notice--strong\" data-reveal><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#shield-check\"/></svg><p data-locked=\"noBlastingUntil\"></p></aside>\n    <div class=\"block\" data-hide-empty=\"risk.hazards\" data-reveal>\n      <h3 class=\"h4\">Preliminary hazard and control register</h3>\n      <div class=\"tbl-wrap\">\n        <table class=\"tbl tbl--register\" data-ratings=\"off\">\n          <thead><tr><th scope=\"col\">Hazard</th><th scope=\"col\">Preliminary control</th><th scope=\"col\" class=\"col-rating\">Residual rating</th><th scope=\"col\" class=\"col-owner\">Owner</th></tr></thead>\n          <tbody data-rows=\"risk.hazards\"><tr data-row><th scope=\"row\" class=\"term\" data-col=\"hazard\"></th><td data-col=\"control\" data-label=\"Preliminary control\"></td><td class=\"col-rating\" data-col=\"rating\" data-label=\"Residual rating\"></td><td class=\"col-owner\" data-col=\"owner\" data-label=\"Owner\"></td></tr></tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"block\" data-hide-empty=\"risk.holdPoints\">\n      <h3 class=\"h4\" data-reveal>Hold points</h3>\n      <ol class=\"holds\" data-rows=\"risk.holdPoints\">\n        <li class=\"hold\" data-row data-reveal>\n          <div class=\"hold-top\"><span class=\"hold-code\" data-col=\"code\"></span><span class=\"chip chip--paper\" data-hold-status><span class=\"chip-dot\" aria-hidden=\"true\"></span><span data-col=\"statusLabel\"></span></span></div>\n          <h4 class=\"hold-title\" data-col=\"title\"></h4>\n          <p data-col=\"requirement\"></p>\n        </li>\n      </ol>\n    </div>\n    <div class=\"block\" data-hide-empty=\"risk.review\" data-reveal>\n      <h3 class=\"h4\">Review and variation</h3>\n      <div class=\"prose prose--wide\" data-paras=\"risk.review\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- 12 DOCUMENTATION ==================================================== -->\n<section id=\"docs\" class=\"sec\" data-sec=\"docs\" data-label=\"Documentation we will provide\" data-surface=\"raised\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Documentation we will provide</h2></div>\n    <ul class=\"doccards\" data-rows=\"docs.items\">\n      <li class=\"doccard\" data-row data-reveal>\n        <div class=\"doccard-top\"><span class=\"doccard-id\" data-col=\"id\"></span><span class=\"doccard-code\" data-col=\"code\"></span></div>\n        <p class=\"doccard-title\" data-col=\"title\"></p>\n        <p class=\"doccard-cat\" data-col=\"category\"></p>\n        <p class=\"doccard-note\" data-col=\"note\"></p>\n      </li>\n    </ul>\n    <div class=\"block\" data-hide-empty=\"docs.projectDocs\" data-reveal>\n      <h3 class=\"h4\">Project documents</h3>\n      <ul class=\"ticks ticks--dark\" data-rows=\"docs.projectDocs\"><li data-row><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#file-text\"/></svg><span><strong data-col=\"title\"></strong> <span data-col=\"note\"></span></span></li></ul>\n    </div>\n    <div class=\"block workflow\" data-hide-empty=\"docs.workflow.on\" data-reveal>\n      <h3 class=\"h4\">How the paperwork follows the explosives</h3>\n      <p class=\"workflow-intro\" data-snap=\"workflow.intro\"></p>\n      <ol class=\"flow\" data-workflow></ol>\n    </div>\n  </div>\n</section>\n\n<!-- 13 EXPLOSIVES LOGISTICS AND SECURITY (off by default) =============== -->\n<section id=\"logistics\" class=\"sec\" data-sec=\"logistics\" data-label=\"Explosives logistics and security\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Explosives logistics and security</h2></div>\n    <ul class=\"ticks ticks--shield\" data-list=\"logistics.lines\" data-reveal><li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#shield-check\"/></svg><span data-item></span></li></ul>\n  </div>\n</section>\n\n<!-- 14 PERSONNEL AND COMPETENCIES ======================================= -->\n<section id=\"team\" class=\"sec\" data-sec=\"team\" data-label=\"Personnel and competencies\" data-surface=\"ink\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Personnel and competencies</h2></div>\n    <div class=\"people\" data-rows=\"team.people\">\n      <article class=\"person\" data-row data-reveal>\n        <div class=\"person-photo\"><img data-col-img=\"photo\" alt=\"\" sizes=\"(max-width: 640px) 100vw, 280px\" loading=\"lazy\"><span class=\"person-mono\" data-col=\"monogram\" aria-hidden=\"true\"></span></div>\n        <div class=\"person-body\">\n          <h3 class=\"h3\" data-col=\"name\"></h3>\n          <p class=\"label label--gold\" data-col=\"role\"></p>\n          <div class=\"prose prose--dark\" data-col-paras=\"bio\"></div>\n          <div class=\"person-comp\" data-col-hide-empty=\"competencies\">\n            <p class=\"label\">Units of competency and licences</p>\n            <ul class=\"comp\" data-col-list=\"competencies\"><li data-item></li></ul>\n          </div>\n          <p class=\"fineprint fineprint--dark\" data-col=\"evidence\"></p>\n        </div>\n      </article>\n    </div>\n    <aside class=\"policy\" data-reveal>\n      <p class=\"kicker\" data-snap=\"competency.heading\"></p>\n      <p data-snap=\"competency.body\"></p>\n    </aside>\n  </div>\n</section>\n\n<!-- 15 PROGRAMME AND MOBILISATION ======================================= -->\n<section id=\"programme\" class=\"sec\" data-sec=\"programme\" data-label=\"Programme and mobilisation\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Programme and mobilisation</h2></div>\n    <dl class=\"meta-grid meta-grid--5\" data-reveal>\n      <div><dt>Proposed start</dt><dd data-field=\"programme.startText\" data-empty=\"—\">—</dd></div>\n      <div><dt>Proposed finish</dt><dd data-field=\"programme.finishText\" data-empty=\"—\">—</dd></div>\n      <div><dt>Duration</dt><dd data-field=\"programme.duration\" data-empty=\"—\">—</dd></div>\n      <div><dt>Shift pattern</dt><dd data-field=\"programme.shiftPattern\" data-empty=\"—\">—</dd></div>\n      <div><dt>Mobilisation lead time</dt><dd data-field=\"programme.leadTime\" data-empty=\"—\">—</dd></div>\n    </dl>\n    <div class=\"timeline\" data-timeline data-hide-empty=\"programme.phases\" data-reveal>\n      <div class=\"timeline-axis\" data-timeline-axis aria-hidden=\"true\"></div>\n      <ol class=\"timeline-rows\" data-timeline-rows></ol>\n    </div>\n    <div class=\"block\" data-hide-empty=\"programme.dependencies\" data-reveal>\n      <h3 class=\"h4\">What we need from you</h3>\n      <ul class=\"diamonds\" data-list=\"programme.dependencies\"><li data-item></li></ul>\n    </div>\n  </div>\n</section>\n\n<!-- 16 QUOTATION ======================================================== -->\n<section id=\"quote\" class=\"sec\" data-sec=\"quote\" data-label=\"Quotation\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Quotation</h2></div>\n    <p class=\"fineprint quote-hint\" data-quote-hint hidden>Optional items are marked. Tick any you would like included; the total updates and your selection is recorded when you accept.</p>\n    <div class=\"tbl-wrap\" data-reveal>\n      <table class=\"tbl tbl--quote\">\n        <thead><tr><th scope=\"col\">Description</th><th scope=\"col\">Basis</th><th scope=\"col\" class=\"num\">Qty</th><th scope=\"col\">Unit</th><th scope=\"col\" class=\"num\">Rate</th><th scope=\"col\" class=\"num\">Amount</th></tr></thead>\n        <tbody data-quote-lines></tbody>\n      </table>\n    </div>\n    <div class=\"totals\" data-reveal>\n      <dl aria-live=\"polite\">\n        <div><dt>Subtotal</dt><dd data-field=\"quote.subtotalText\" data-empty=\"—\">—</dd></div>\n        <div><dt>GST 10%</dt><dd data-field=\"quote.gstText\" data-empty=\"—\">—</dd></div>\n        <div class=\"totals-total\"><dt>Total inc GST</dt><dd data-field=\"quote.totalText\" data-empty=\"—\">—</dd></div>\n      </dl>\n      <p class=\"fineprint\" data-field=\"quote.atCostNote\" data-empty=\"\"></p>\n    </div>\n    <dl class=\"meta-grid meta-grid--terms\" data-quote-terms data-reveal></dl>\n    <div class=\"cols2\">\n      <div class=\"block\" data-hide-empty=\"quote.assumptions\" data-reveal>\n        <h3 class=\"h4\">Assumptions</h3>\n        <ul class=\"diamonds\" data-list=\"quote.assumptions\"><li data-item></li></ul>\n      </div>\n      <div class=\"block\" data-hide-empty=\"quote.exclusions\" data-reveal>\n        <h3 class=\"h4\">Exclusions</h3>\n        <ul class=\"ticks ticks--minus\" data-list=\"quote.exclusions\"><li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#minus\"/></svg><span data-item></span></li></ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 17 DOCUMENTS AND ATTACHMENTS ======================================== -->\n<section id=\"attachments\" class=\"sec\" data-sec=\"attachments\" data-label=\"Documents and attachments\" data-surface=\"raised\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Documents and attachments</h2></div>\n    <div data-attachments></div>\n  </div>\n</section>\n\n<!-- 18 TERMS, ASSUMPTIONS AND DISCLAIMERS =============================== -->\n<section id=\"terms\" class=\"sec\" data-sec=\"terms\" data-label=\"Terms and disclaimers\" data-surface=\"paper\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Terms, assumptions and disclaimers</h2></div>\n    <details class=\"terms\" data-hide-empty=\"terms.body\" data-reveal>\n      <summary><span>Terms and conditions</span><span class=\"terms-ver\">Version <span data-field=\"terms.version\" data-empty=\"—\">—</span></span><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#chevron-down\"/></svg></summary>\n      <div class=\"prose prose--wide\" data-paras=\"terms.body\"></div>\n    </details>\n    <ul class=\"statements\" data-reveal>\n      <li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#file-check\"/></svg><p data-locked=\"preliminaryStatus\"></p></li>\n      <li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#shield-check\"/></svg><p data-snap=\"assurance.body\"></p></li>\n      <li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#phone\"/></svg><p data-locked=\"misfire\"></p></li>\n      <li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#alert-triangle\"/></svg><p data-locked=\"emergency000\"></p></li>\n    </ul>\n  </div>\n</section>\n\n<!-- 19 ACCEPTANCE ======================================================= -->\n<section id=\"accept\" class=\"sec\" data-sec=\"accept\" data-label=\"Acceptance\" data-surface=\"ink\">\n  <div class=\"wrap\">\n    <div class=\"sec-head\" data-reveal><span class=\"sec-num\" data-secnum></span><h2 class=\"h2\">Acceptance</h2></div>\n    <p class=\"accept-banner\" data-accept-banner role=\"status\" hidden></p>\n    <div class=\"accept\">\n      <div class=\"accept-summary\" data-reveal>\n        <aside class=\"notice notice--dark\"><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#shield-check\"/></svg><p data-locked=\"hp1Framing\"></p></aside>\n        <dl class=\"accept-dl\">\n          <div><dt>Reference</dt><dd data-field=\"meta.reference\" data-empty=\"Allocated on issue\">Allocated on issue</dd></div>\n          <div><dt>Revision</dt><dd data-field=\"meta.revLabel\" data-empty=\"—\">—</dd></div>\n          <div><dt>Optional items</dt><dd data-field=\"quote.optionsText\" data-empty=\"None selected\" data-live>None selected</dd></div>\n          <div class=\"accept-total\"><dt>Total inc GST</dt><dd data-field=\"quote.totalText\" data-empty=\"—\" data-live>—</dd></div>\n        </dl>\n        <p class=\"fineprint fineprint--dark\" data-field=\"accept.holdNote\" data-empty=\"Planning and site preparation can begin once this is accepted.\">Planning and site preparation can begin once this is accepted.</p>\n      </div>\n      <div class=\"accept-side\">\n        <form class=\"accept-form\" data-accept-form novalidate data-reveal>\n          <div class=\"field-row\">\n            <label class=\"field\"><span class=\"field-label\">Full name</span><input name=\"name\" autocomplete=\"name\" required maxlength=\"120\" data-prefill=\"client.contactName\"></label>\n            <label class=\"field\"><span class=\"field-label\">Position</span><input name=\"position\" autocomplete=\"organization-title\" required maxlength=\"120\" data-prefill=\"client.contactPosition\"></label>\n          </div>\n          <div class=\"field-row\">\n            <label class=\"field\"><span class=\"field-label\">Company</span><input name=\"company\" autocomplete=\"organization\" required maxlength=\"200\" data-prefill=\"client.company\"></label>\n            <label class=\"field\"><span class=\"field-label\">Email</span><input name=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"200\"></label>\n          </div>\n          <label class=\"check\"><input type=\"checkbox\" name=\"authority\" required><span>I have authority to accept on behalf of <span data-field=\"client.company\" data-empty=\"the company\"></span>.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"accept\" required><span data-field=\"accept.clause\" data-empty=\"\"></span></label>\n          <fieldset class=\"sig\" data-sig>\n            <legend class=\"field-label\">Signature</legend>\n            <p class=\"sig-hint\" data-sig-hint>Draw your signature, or type your full name below. Either is enough.</p>\n            <div class=\"sig-pad\" data-sig-draw>\n              <canvas class=\"sig-canvas\" data-sig-canvas role=\"img\" aria-label=\"Signature pad. Draw with a finger, stylus or mouse.\" width=\"600\" height=\"180\"></canvas>\n              <button type=\"button\" class=\"sig-clear\" data-sig-clear>Clear</button>\n            </div>\n            <label class=\"field\" data-sig-type><span class=\"field-label\">Type your full name</span><input name=\"typed\" class=\"sig-typed\" autocomplete=\"off\" maxlength=\"120\"></label>\n          </fieldset>\n          <div class=\"accept-actions\">\n            <button type=\"submit\" class=\"btn btn--primary btn--lg btn--glow\" data-accept-go>Accept proposal</button>\n            <button type=\"button\" class=\"btn btn--secondary btn--lg\" data-request-changes aria-expanded=\"false\" aria-controls=\"changes-form\">Request changes</button>\n          </div>\n          <p class=\"accept-note\" data-accept-note role=\"status\" aria-live=\"polite\"></p>\n        </form>\n        <div class=\"accept-done\" data-accept-done tabindex=\"-1\" hidden>\n          <p class=\"accept-done-label\"><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#check-circle\"/></svg><span data-done-label>Accepted</span></p>\n          <p class=\"accept-done-by\" data-done-by></p>\n          <dl class=\"accept-dl\">\n            <div><dt>Accepted</dt><dd data-done-when></dd></div>\n            <div><dt>Optional items</dt><dd data-done-options></dd></div>\n            <div class=\"accept-total\"><dt>Total inc GST</dt><dd data-done-total></dd></div>\n          </dl>\n          <p class=\"fineprint fineprint--dark\" data-field=\"accept.holdMet\" data-empty=\"\"></p>\n        </div>\n        <form class=\"changes-form\" id=\"changes-form\" data-changes-form novalidate hidden>\n          <h3 class=\"h4\">Request changes</h3>\n          <p class=\"changes-intro\">Tell us what you would like changed. Nothing is accepted, and this proposal stays open.</p>\n          <div class=\"field-row\">\n            <label class=\"field\"><span class=\"field-label\">Your name</span><input name=\"name\" autocomplete=\"name\" required maxlength=\"120\"></label>\n            <label class=\"field\"><span class=\"field-label\">Email</span><input name=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"200\"></label>\n          </div>\n          <label class=\"field\"><span class=\"field-label\">What would you like changed?</span><textarea name=\"message\" rows=\"5\" required maxlength=\"2000\"></textarea></label>\n          <div class=\"accept-actions\">\n            <button type=\"submit\" class=\"btn btn--primary btn--lg\" data-changes-go>Send the request</button>\n            <button type=\"button\" class=\"btn btn--secondary btn--lg\" data-changes-cancel>Cancel</button>\n          </div>\n          <p class=\"accept-note\" data-changes-note role=\"status\" aria-live=\"polite\"></p>\n        </form>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 20 CONTACT ========================================================== -->\n<footer id=\"contact\" class=\"sec foot\" data-sec=\"contact\" data-label=\"Contact\" data-surface=\"raised\">\n  <div class=\"wrap\">\n    <h2 class=\"sr-only\">Contact</h2>\n    <div class=\"foot-grid\">\n      <div class=\"foot-brand\">\n        <img src=\"/assets/img/logo/TEXC-Gold.svg\" alt=\"TEXC\" width=\"102\" height=\"40\" loading=\"lazy\">\n        <p class=\"foot-tagline\">The Explosive Contractor. Wherever you need one.</p>\n        <p class=\"foot-legal\">TEXC Pty Ltd · ABN 47 688 368 881</p>\n      </div>\n      <div class=\"foot-person\">\n        <img class=\"foot-photo\" data-img=\"contact.photo\" alt=\"\" width=\"72\" height=\"82\" loading=\"lazy\">\n        <div>\n          <p class=\"foot-name\">George Scott</p>\n          <p class=\"label label--gold\">Managing Director | Licensed Shotfirer</p>\n          <ul class=\"foot-links\">\n            <li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#phone\"/></svg><a href=\"tel:0467651182\">0467 651 182</a></li>\n            <li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#mail\"/></svg><a href=\"mailto:management@texc.au\">management@texc.au</a></li>\n            <li><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#globe\"/></svg><a href=\"https://texc.au\" rel=\"noopener\">texc.au</a></li>\n          </ul>\n        </div>\n      </div>\n      <dl class=\"foot-ref\">\n        <div><dt>Reference</dt><dd data-field=\"meta.reference\" data-empty=\"Allocated on issue\">Allocated on issue</dd></div>\n        <div><dt>Revision</dt><dd data-field=\"meta.revLabel\" data-empty=\"—\">—</dd></div>\n        <div><dt>Prepared by</dt><dd>TEXC Pty Ltd</dd></div>\n      </dl>\n    </div>\n    <div class=\"foot-bottom\">\n      <p class=\"foot-line\" data-field=\"meta.footerLine\" data-empty=\"TEXC Pty Ltd · ABN 47 688 368 881\">TEXC Pty Ltd · ABN 47 688 368 881</p>\n      <p class=\"foot-revs\" data-revisions hidden>Revisions: <span data-revision-links></span></p>\n      <a href=\"/privacy/\">Privacy</a>\n    </div>\n  </div>\n</footer>\n\n</main>\n\n<button type=\"button\" id=\"flt\" class=\"flt\" aria-label=\"Back to top\"><svg class=\"ic\" aria-hidden=\"true\"><use href=\"/assets/img/icons.svg#arrow-up\"/></svg></button>\n</body>\n</html>\n";
